use super::*;
use client::{Client, Control};
use protocol::{Command, Empty, Text};
use parking_lot::Mutex;
use std::{collections::HashSet, sync::mpsc};
use serde_json::Value;

pub struct PiBackend {
    config: config::Agentd,
    client: once_cell::sync::OnceCell<Arc<Client>>,
    preparing: Arc<Mutex<HashSet<String>>>,
    cancelled: Arc<Mutex<HashSet<String>>>,
}
impl PiBackend {
    pub fn new(config: config::Agentd) -> anyhow::Result<Self> {
        config::Config { agent: config::Agent::default(), agentd: config.clone() }.validate()?;
        Ok(Self { config, client: once_cell::sync::OnceCell::new(),
            preparing: Arc::new(Mutex::new(HashSet::new())), cancelled: Arc::new(Mutex::new(HashSet::new())) })
    }
    fn client(&self) -> anyhow::Result<Arc<Client>> {
        if self.config.isolation == "per-account" { return Err(BackendError::AccountContextRequired.into()); }
        self.client.get_or_try_init(|| Client::new(self.config.clone())).cloned()
    }
    /// Process-wide configuration; close every session reported by the daemon.
    pub fn apply_config(&self, config: Option<Value>, credentials: Option<Value>) -> anyhow::Result<Value> {
        let client = self.client()?;
        anyhow::ensure!(client.active.lock().is_empty(), "AgentdConfigBusy");
        let result = client.call(Command::Apply(protocol::Apply { config, credentials }))?;
        if let Some(ids) = result.get("reopenRequired").and_then(Value::as_array) {
            for id in ids {
                if let Some(id) = id.as_str() { client.call(Command::Close(protocol::Session { session_id: id.into() }))?; }
            }
        }
        Ok(result)
    }
}
impl AgentBackend for PiBackend {
    fn start(&self, input: TurnRequest) -> anyhow::Result<EventStream> {
        if self.config.isolation == "per-account" {
            return Err(if input.account_id.is_some() { BackendError::UnsupportedIsolation } else { BackendError::AccountContextRequired }.into());
        }
        anyhow::ensure!(input.attachments.is_empty(), BackendError::UnsupportedInput("binary attachments are absent from the agentd prompt schema"));
        anyhow::ensure!(!input.prompt.trim().is_empty(), "AgentdEmptyPrompt");
        let client = self.client()?;
        if client.status.lock().circuit_open { return Err(BackendError::CircuitOpen.into()); }
        let (sender, stream) = stream::Mailbox::channel(self.config.channel_capacity, self.config.max_line_bytes);
        let preparing = self.preparing.clone();
        let cancelled = self.cancelled.clone();
        anyhow::ensure!(preparing.lock().insert(input.req_id.clone()), "AgentdDuplicateRequest");
        let key = format!("session:{}", input.session_id);
        if !preparing.lock().insert(key.clone()) {
            preparing.lock().remove(&input.req_id);
            anyhow::bail!("AgentdSessionBusy");
        }
        std::thread::spawn(move || {
            let req = input.req_id.clone();
            let conv = input.conversation_id.clone();
            let mut registered = false;
            let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| -> anyhow::Result<()> {
                sender.push_blocking(event(&req, conv.as_deref(), "meta",
                    Some(crate::chat::prompt::estimate_tokens(&input.prompt).to_string())));
                if cancelled.lock().remove(&req) { sender.finish(None, event(&req, conv.as_deref(), "done", None)); return Ok(()); }
                let info = sessions::open(&client, &input)?;
                if matches!(input.permission, PermissionMode::Deny | PermissionMode::Manual) {
                    anyhow::ensure!(info.tools.iter().all(|t| client.config.readonly_tools.contains(t)),
                        BackendError::UnsupportedInput("read-only/manual request cannot use a daemon with write or execution tools"));
                }
                if let Some(model) = &input.model {
                    anyhow::ensure!(model == &info.model, BackendError::UnsupportedInput("model selection is process-wide; apply config before opening sessions"));
                }
                let (tx, rx) = mpsc::sync_channel(1);
                client.send(Control::Register { session: info.id.clone(), req: req.clone(),
                    translator: translate::Translator::new(req.clone(), conv.clone(), input.cwd.clone(), &client.config),
                    stream: sender.clone(), timeout: input.timeout.unwrap_or(Duration::from_millis(client.config.turn_timeout_ms)), reservation: (preparing.clone(), key.clone()), reply: tx })?;
                client.wait(rx)?;
                registered = true;
                let result = client.call(Command::Prompt(Text { session_id: info.id.clone(), text: input.prompt }));
                eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                    "reqId":req, "conversationId":conv, "sessionId":info.id, "phase":"prompt", "ok":result.is_ok()}));
                let result = result?;
                let turn = result.get("turnId").and_then(Value::as_str).ok_or_else(|| anyhow::anyhow!("AgentdMissingTurnId"))?;
                let (tx, rx) = mpsc::sync_channel(1);
                client.send(Control::Bind(req.clone(), turn.into(), tx))?;
                client.wait(rx)?;
                if cancelled.lock().remove(&req) { client.cancel(&req)?; }
                Ok(())
            }));
            let error = match result { Ok(Ok(())) => None, Ok(Err(e)) => Some(e.to_string()), Err(_) => Some("AgentdPreparationPanic".into()) };
            if let Some(error) = error {
                if registered {
                    let _ = client.send(Control::Fail(req.clone(), error));
                } else {
                    sender.finish(Some(event(&req, conv.as_deref(), "error", Some(error))), event(&req, conv.as_deref(), "done", None));
                }
            }
            preparing.lock().remove(&req);
            if !registered { preparing.lock().remove(&key); }
            cancelled.lock().remove(&req);
        });
        Ok(stream)
    }
    fn cancel(&self, req: &str) -> anyhow::Result<()> {
        if self.preparing.lock().contains(req) { self.cancelled.lock().insert(req.into()); }
        if let Some(client) = self.client.get() { client.cancel(req)?; }
        Ok(())
    }
    fn close(&self, session: &str) -> anyhow::Result<()> {
        if let Some(client) = self.client.get() { sessions::close(client, session)?; }
        Ok(())
    }
    fn models(&self) -> anyhow::Result<Value> { self.client()?.call(Command::Models(Empty {})) }
    fn status(&self) -> BackendStatus {
        self.client.get().map(|c| c.status.lock().clone()).unwrap_or_else(|| BackendStatus::new("pi"))
    }
    fn is_running(&self, req: &str) -> bool {
        self.preparing.lock().contains(req) || self.client.get().is_some_and(|c| c.active.lock().contains_key(req))
    }
    fn shutdown(&self) { if let Some(client) = self.client.get() { client.stop(); } }
}
impl Drop for PiBackend { fn drop(&mut self) { self.shutdown(); } }

use super::{client::{Control, Reply}, process::Process, protocol::{Command, Empty, Frame, Id, Request, Session}, routes::Route};
use super::super::{config::Agentd, BackendStatus, BackendError};
use parking_lot::Mutex;
use std::{collections::HashMap, sync::Arc, time::{Duration, Instant}};
use tokio::sync::mpsc;
use serde_json::{Value, json};
struct Pending { reply: Option<Reply>, since: Instant }
struct State {
    config: Agentd,
    status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>,
    routes: HashMap<String, Route>,
    pending: HashMap<Id, Pending>,
    counter: u64,
    failures: u32,
    next_start: Instant,
    last_ping: Instant,
    started: Instant,
    last_used: Instant,
    stopping: bool,
}
impl State {
    fn request(&mut self, process: &Process, command: Command, reply: Option<Reply>) -> anyhow::Result<()> {
        self.counter += 1;
        let id = Id::Text(format!("rust-{}", self.counter));
        process.write(&Request { id: id.clone(), command }, self.config.max_line_bytes)?;
        self.pending.insert(id, Pending { reply, since: Instant::now() });
        Ok(())
    }
    fn fail(&mut self, error: String) {
        self.failures = self.failures.saturating_add(1);
        let circuit = self.failures >= self.config.failure_threshold;
        let error = if circuit { format!("{}: {error}", BackendError::CircuitOpen) } else { error };
        for route in self.routes.values_mut() { route.fail(&error); }
        let mut status = self.status.lock();
        status.healthy = false;
        status.pid = None;
        status.circuit_open = circuit;
        eprintln!("{}", json!({"component":"agent.backend", "backend":"pi", "phase":"failure", "error":error}));
        status.last_error = Some(error.clone());
        drop(status);
        for (_, pending) in self.pending.drain() {
            if let Some(reply) = pending.reply { let _ = reply.send(Err(error.clone())); }
        }
        let backoff = self.config.restart_base_ms.saturating_mul(1_u64 << self.failures.saturating_sub(1).min(30))
            .min(self.config.restart_max_ms);
        let mut bytes = [0_u8; 8];
        let _ = getrandom::getrandom(&mut bytes);
        let jitter = u64::from_le_bytes(bytes) % self.config.restart_jitter_ms.saturating_add(1).max(1);
        self.next_start = Instant::now() + Duration::from_millis(backoff.saturating_add(jitter).min(self.config.restart_max_ms));
    }
    fn frame(&mut self, frame: Frame) -> anyhow::Result<()> {
        match frame {
            Frame::Response { id, ok, result, error } => {
                let id = id.ok_or_else(|| anyhow::anyhow!("AgentdProtocolError: uncorrelated response"))?;
                if let Some(pending) = self.pending.remove(&id) {
                    let result = if ok { Ok(result.unwrap_or(Value::Null)) }
                        else { Err(error.map(|e| format!("{}: {}", e.code, e.message)).unwrap_or_else(|| "AgentdResponseError".into())) };
                    if let Some(reply) = pending.reply { let _ = reply.send(result); }
                    else {
                        let value = result.map_err(anyhow::Error::msg)?;
                        anyhow::ensure!(value.get("status").and_then(Value::as_str) == Some("ok"), "AgentdPingFailed");
                        self.status.lock().healthy = true;
                    }
                }
            }
            Frame::Event { session_id, turn_id, event } => {
                if let Some(route) = self.routes.get_mut(&session_id) { route.accept(turn_id, event)?; }
                // Events after a locally finalized abort are intentionally ignored.
            }
        }
        Ok(())
    }
    fn control(&mut self, command: Control, process: Option<&Process>) -> anyhow::Result<()> {
        self.last_used = Instant::now();
        match command {
            Control::Stop => { self.stopping = true; }
            Control::Fail(req, message) => {
                for route in self.routes.values_mut().filter(|r| r.req == req) { route.fail(&message); }
            }
            Control::Register { session, req, translator, stream, timeout, reservation, reply } => {
                if self.routes.contains_key(&session) {
                    let _ = reply.send(Err("AgentdSessionBusy".into()));
                } else if process.is_none() {
                    let _ = reply.send(Err(self.unavailable()));
                } else {
                    self.active.lock().insert(req.clone(), session.clone());
                    self.routes.insert(session.clone(), Route { req, session, active: self.active.clone(), acknowledged: false, started: false, reservation, turn: None, translator, stream,
                        deadline: Instant::now() + timeout, abort_deadline: None,
                        pending: Default::default(), terminal: None, first_error: None });
                    let _ = reply.send(Ok(json!({})));
                }
            }
            Control::Request(command, reply) => {
                if let Some(process) = process {
                    if let Err(e) = self.request(process, command, Some(reply.clone())) {
                        let _ = reply.send(Err(e.to_string()));
                        return Err(e);
                    }
                } else { let _ = reply.send(Err(self.unavailable())); }
            }
            Control::Bind(req, turn, reply) => {
                let route = self.routes.values_mut().find(|r| r.req == req);
                let result = match route {
                    Some(route) if route.turn.as_ref().is_none_or(|id| id == &turn) => {
                        route.turn = Some(turn);
                        route.acknowledged = true;
                        Ok(json!({}))
                    }
                    Some(route) => { route.fail("AgentdTurnMismatch"); Err("AgentdTurnMismatch".into()) }
                    None => Err("AgentdTurnMissing".into()),
                };
                let _ = reply.send(result);
            }
            Control::Cancel(req, reply) => {
                let session = self.active.lock().get(&req).cloned();
                if let Some(session) = session {
                    if let Some(route) = self.routes.get_mut(&session) {
                        route.abort_deadline = Some(Instant::now() + Duration::from_millis(self.config.abort_timeout_ms));
                    }
                    if let Some(process) = process {
                        // Abort response may arrive after turn.completed. Ignore only its result,
                        // using an ordinary reply prevents it being mistaken for a health ping.
                        let (tx, _rx) = std::sync::mpsc::sync_channel(1);
                        self.request(process, Command::Abort(Session { session_id: session }), Some(tx))?;
                    }
                }
                let _ = reply.send(Ok(json!({"accepted":true})));
            }
        }
        Ok(())
    }
    fn unavailable(&self) -> String {
        let status = self.status.lock();
        if status.circuit_open { BackendError::CircuitOpen.to_string() }
        else { status.last_error.clone().unwrap_or_else(|| "AgentdRestarting".into()) }
    }
    fn drain(&mut self) -> bool {
        let mut ready = true;
        self.routes.retain(|_, route| {
            route.tick();
            ready &= route.drain();
            if route.stream.is_finished() { self.active.lock().remove(&route.req); false } else { true }
        });
        ready
    }
    fn deadlines(&mut self, process: Option<&Process>) -> anyhow::Result<()> {
        if let Some(error) = process.and_then(Process::write_error) { anyhow::bail!(error); }
        for route in self.routes.values_mut() {
            if route.abort_deadline.is_some_and(|d| Instant::now() >= d) {
                route.aborted();
                anyhow::bail!("AgentdAbortTimeout: daemon restarted to stop the cancelled turn");
            }
            if Instant::now() >= route.deadline && route.terminal.is_none() {
                route.fail("AgentdTurnTimeout");
                anyhow::bail!("AgentdTurnTimeout");
            }
        }
        if self.pending.values().any(|p| p.since.elapsed().as_millis() >= self.config.request_timeout_ms as u128) {
            if process.is_some_and(Process::writes_pending) { anyhow::bail!(super::process::WRITER_BACKPRESSURE); }
            anyhow::bail!("AgentdRequestTimeout");
        }
        Ok(())
    }
}
// Also runs when the supervisor future is dropped or its thread unwinds.
impl Drop for State {
    fn drop(&mut self) { self.active.lock().clear(); }
}
pub async fn run(config: Agentd, mut rx: mpsc::Receiver<Control>, status: Arc<Mutex<BackendStatus>>,
    active: Arc<Mutex<HashMap<String, String>>>) {
    let now = Instant::now();
    let mut s = State { config, status, active, routes: HashMap::new(), pending: HashMap::new(),
        counter: 0, failures: 0, next_start: now, last_ping: now, started: now, last_used: now, stopping: false };
    let mut process: Option<Process> = None;
    let mut ever_started = false;
    let mut idle = false;
    let mut ticker = tokio::time::interval(Duration::from_millis(s.config.supervisor_tick_ms));
    loop {
        if !idle && process.is_none() && !s.status.lock().circuit_open && Instant::now() >= s.next_start {
            match Process::spawn(&s.config) {
                Ok(p) => {
                    { let mut status = s.status.lock(); status.pid = Some(p.pid); if ever_started { status.restarts += 1; } }
                    ever_started = true;
                    s.started = Instant::now();
                    s.last_ping = Instant::now();
                    if let Err(e) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(e.to_string()); }
                    process = Some(p);
                }
                Err(e) => s.fail(e.to_string()),
            }
        }
        let ready = s.drain();
        let outcome: anyhow::Result<()> = tokio::select! {
            command = rx.recv() => {
                match command {
                    Some(command) => {
                        if idle {
                            idle = false;
                            match Process::spawn(&s.config) {
                                Ok(p) => {
                                    { let mut status = s.status.lock(); status.pid = Some(p.pid); status.restarts += 1; }
                                    s.started = Instant::now();
                                    s.last_ping = Instant::now();
                                    if let Err(error) = s.request(&p, Command::Ping(Empty {}), None) { s.fail(error.to_string()); }
                                    process = Some(p);
                                }
                                Err(e) => s.fail(e.to_string()),
                            }
                        }
                        s.control(command, process.as_ref())
                    }
                    None => { s.stopping = true; Ok(()) }
                }
            }
            frame = async { match &mut process { Some(p) => p.incoming.recv().await, None => std::future::pending().await } }, if ready => {
                match frame { Some(Ok(frame)) => s.frame(frame), Some(Err(e)) => Err(e), None => Err(anyhow::anyhow!("AgentdEof")) }
            }
            _ = ticker.tick() => {
                let deadlines = s.deadlines(process.as_ref());
                if let Some(p) = &mut process {
                    if p.exited().unwrap_or(true) { Err(anyhow::anyhow!("AgentdExited")) }
                    else if deadlines.is_err() { deadlines }
                    else if ready && s.last_ping.elapsed().as_millis() >= s.config.ping_interval_ms as u128 {
                        s.last_ping = Instant::now();
                        s.request(p, Command::Ping(Empty {}), None)
                    } else {
                        if s.status.lock().healthy && s.started.elapsed().as_millis() >= s.config.stable_reset_ms as u128 { s.failures = 0; }
                        Ok(())
                    }
                } else { deadlines }
            }
        };
        if let Err(error) = outcome {
            s.fail(error.to_string());
            if let Some(mut p) = process.take() { p.stop().await; }
        }
        if s.stopping {
            for route in s.routes.values_mut() { route.fail("AgentdShutdown"); }
            if let Some(mut p) = process.take() { p.stop().await; }
            // Delivery is cancellable by dropping the receiver; keep draining retained events.
            while !s.routes.is_empty() { s.drain(); ticker.tick().await; }
            break;
        }
        if process.is_some() && s.routes.is_empty() && s.pending.is_empty()
            && s.last_used.elapsed().as_millis() >= s.config.idle_ms as u128 {
            if let Some(mut p) = process.take() { p.stop().await; }
            let mut status = s.status.lock(); status.pid = None; status.healthy = false;
            idle = true;
        }
    }
    let mut status = s.status.lock(); status.pid = None; status.healthy = false;
}
use super::{translate::Translator, protocol::{Event, TurnStatus}};
use super::super::stream::Mailbox;
use crate::chat::ChatStreamEvent;
use std::{collections::VecDeque, sync::Arc, time::Instant};
pub struct Route {
    pub req: String,
    pub session: String,
    pub active: Arc<parking_lot::Mutex<std::collections::HashMap<String, String>>>,
    pub acknowledged: bool,
    pub started: bool,
    pub reservation: (Arc<parking_lot::Mutex<std::collections::HashSet<String>>>, String),
    pub turn: Option<String>,
    pub translator: Translator,
    pub stream: Arc<Mailbox>,
    pub deadline: Instant,
    pub abort_deadline: Option<Instant>,
    pub pending: VecDeque<ChatStreamEvent>,
    pub terminal: Option<(Option<ChatStreamEvent>, ChatStreamEvent)>,
    pub first_error: Option<String>,
}
impl Route {
    pub fn accept(&mut self, turn: String, event: Event) -> anyhow::Result<()> {
        if self.terminal.is_some() || self.stream.is_finished() { return Ok(()); }
        if !self.started {
            anyhow::ensure!(matches!(event, Event::Started), "AgentdTurnOrder: expected turn.started");
            self.started = true;
            if self.turn.is_none() { self.turn = Some(turn.clone()); }
        }
        anyhow::ensure!(self.turn.as_deref() == Some(&turn), "AgentdTurnMismatch");
        let fatal = matches!(event, Event::Error { .. } | Event::Completed { .. });
        let events = self.translator.accept(event);
        if fatal && self.first_error.is_none() {
            self.first_error = events.iter().find(|e| e.kind == "error").and_then(|e| e.text.clone());
        }
        self.enqueue(events);
        Ok(())
    }
    pub fn tick(&mut self) {
        if self.terminal.is_none() { let events = self.translator.tick(); self.enqueue(events); }
    }
    fn enqueue(&mut self, events: Vec<ChatStreamEvent>) {
        for event in events {
            if event.kind == "done" { self.terminal = Some((None, event)); }
            else { self.pending.push_back(event); }
        }
    }
    pub fn fail(&mut self, message: &str) {
        if self.stream.is_finished() { return; }
        self.acknowledged = true;
        let error = if self.first_error.is_some() {
            eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                "reqId":self.req, "phase":"secondary-error", "error":message, "firstError":self.first_error}));
            None
        } else {
            self.first_error = Some(message.into());
            Some(self.translator.make("error", Some(message.into())))
        };
        if let Some((existing, _)) = &mut self.terminal {
            if existing.is_none() { *existing = error; }
            return;
        }
        let events = self.translator.flush();
        self.enqueue(events);
        self.terminal = Some((error, self.translator.make("done", None)));
    }
    pub fn aborted(&mut self) {
        if self.terminal.is_none() {
            let events = self.translator.accept(Event::Completed { status: TurnStatus::Aborted });
            self.enqueue(events);
        }
    }
    pub fn drain(&mut self) -> bool {
        while let Some(event) = self.pending.pop_front() {
            if let Err(event) = self.stream.try_push(event) {
                self.pending.push_front(event);
                return false;
            }
        }
        if self.acknowledged {
            if let Some((error, done)) = self.terminal.take() {
                eprintln!("{}", serde_json::json!({"component":"agent.backend", "backend":"pi",
                    "reqId":self.req, "conversationId":done.conversation_id, "sessionId":self.session,
                    "phase":"done", "error":error.is_some()}));
                self.reservation.0.lock().remove(&self.reservation.1);
                self.active.lock().remove(&self.req);
                self.stream.finish(error, done);
            }
        }
        true
    }
}

impl Drop for Route {
    fn drop(&mut self) {
        self.reservation.0.lock().remove(&self.reservation.1);
        self.active.lock().remove(&self.req);
    }
}

