fn collect_events(stream: EventStream) -> Vec<crate::chat::ChatStreamEvent> {
    let mut events = vec![];
    loop {
        let e = stream.recv_timeout(Duration::from_secs(5)).expect("terminal event deadline");
        let done = e.kind == "done";
        events.push(e);
        if done { return events; }
    }
}
